  var TASKS = ['lesson', 'retell'], KINDS = ['moral', 'detail', 'wrong', 'other'];
  /* the lesson's slot over the ten fables (a balanced table, rotated by one each pass) */
  var SLOTS = { 3: [0, 1, 2, 0, 1, 2, 0, 1, 2, 0], 4: [0, 1, 2, 3, 0, 1, 2, 3, 1, 2] };
  function locale(l) { l = String(l || 'en').slice(0, 2).toLowerCase(); return DATA.LOCALES.indexOf(l) >= 0 ? l : 'en'; }
