  function same(a, b) { if (!a || !b || a.length !== b.length) return false; for (var i = 0; i < a.length; i++) if (a[i] !== b[i]) return false; return true; }
  function textOf(f, kind) { return kind === 'moral' ? f.m : kind === 'detail' ? f.d : kind === 'wrong' ? f.w : f.other; }
