  function cardsFor(f, r, n, slot) {
    var rest = (r % 2 ? ['wrong', 'detail'] : ['detail', 'wrong']).concat(n === 4 ? ['other'] : []);
    var kinds = rest.slice(0, slot).concat(['moral'], rest.slice(slot));
    return kinds.map(function (k) { return { kind: k, text: textOf(f, k) }; });
  }

  /* ---------------- the state ---------------- */
  function newState(loc, task, n, r, opts) {
    opts = opts || {}; loc = locale(loc); task = taskOf(task); n = nCards(n);
    var f = fable(loc, r), slot = opts.slot == null ? SLOTS[n][r] : opts.slot % n;
    var st = { loc: loc, task: task, n: n, r: r, F: f, cards: cardsFor(f, r, n, slot), right: slot, lantern: null, misses: 0, show: 0, last: null, light: null, done: false };
    st.order = [0, 1, 2]; st.retold = task === 'lesson'; st.sel = null; st.retellMisses = 0; st.misplaced = null;
    if (task === 'retell') { var p = opts.perm; if (!p || p.length !== 3 || same(p, [0, 1, 2])) p = [2, 0, 1]; st.order = p.slice(); }
    return st;
  }
  function help0(st) { st.last = null; st.light = null; st.misplaced = null; }
